import{_ as s,c as i,o as t,ag as a}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"IAM: identities, roles and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"aws/iam-and-security.md","filePath":"aws/iam-and-security.md"}'),n={name:"aws/iam-and-security.md"};function r(o,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="iam-identities-roles-and-permissions" tabindex="-1">IAM: identities, roles and permissions <a class="header-anchor" href="#iam-identities-roles-and-permissions" aria-label="Permalink to “IAM: identities, roles and permissions”">​</a></h1><p>IAM controls access to AWS resources. Start with a concrete question: <strong>which principal may perform which action on which resource, under which conditions?</strong> A principal is the identity making the request.</p><h2 id="identities-and-credentials" tabindex="-1"><span class="hub-section-number">1 </span>Identities and credentials <a class="header-anchor" href="#identities-and-credentials" aria-label="Permalink to “1 Identities and credentials”">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Purpose</th></tr></thead><tbody><tr><td>Root user</td><td>Account identity reserved for exceptional account tasks</td></tr><tr><td>IAM user</td><td>An identity that can have long-lived credentials</td></tr><tr><td>IAM group</td><td>A way to attach permissions to a collection of IAM users</td></tr><tr><td>IAM role</td><td>An assumable identity with a trust policy and permissions</td></tr><tr><td>STS</td><td>Issues temporary security credentials for supported session operations</td></tr><tr><td>Identity Center</td><td>Workforce access to accounts and applications through managed sign-in</td></tr></tbody></table><p>Temporary AWS credentials contain an access key ID, secret access key, session token and expiration. A role&#39;s session duration is configurable within applicable limits; it is not a universal fixed duration. SDKs can obtain and refresh supported role credentials without you copying keys into the application.</p><p>An <strong>ARN</strong> identifies an AWS resource. Its structure depends on the service. S3 bucket ARNs look different from Lambda ARNs; do not invent an ARN by assuming every service uses the same fields.</p><h2 id="policies-are-permission-statements" tabindex="-1"><span class="hub-section-number">2 </span>Policies are permission statements <a class="header-anchor" href="#policies-are-permission-statements" aria-label="Permalink to “2 Policies are permission statements”">​</a></h2><p>This illustrative identity policy permits reads under one S3 prefix:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;Version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2012-10-17&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;Statement&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Effect&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;s3:GetObject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Resource&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;arn:aws:s3:::example-learning-assets/public/*&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>Effect</code> allows or denies, <code>Action</code> names API operations, <code>Resource</code> scopes the target, and optional <code>Condition</code> elements constrain the circumstances. The <code>Version</code> is a policy-language version, not today&#39;s date. <code>Principal</code> identifies who is allowed in relevant resource and trust policies; it does not belong in a normal identity policy.</p><p>Listing a bucket and reading an object are separate actions on different resource types. A policy permitting object reads does not automatically permit <code>ListBucket</code>.</p><h2 id="trust-versus-permission" tabindex="-1"><span class="hub-section-number">3 </span>Trust versus permission <a class="header-anchor" href="#trust-versus-permission" aria-label="Permalink to “3 Trust versus permission”">​</a></h2><p>A role has two separate questions:</p><ul><li><strong>Trust policy:</strong> who may assume this role?</li><li><strong>Permissions policies:</strong> what may a resulting session do?</li></ul><p>A Lambda execution role trusts the Lambda service. Its permissions might allow reading one bucket and writing one table. The person deploying that Lambda is a different principal with deployment permissions.</p><p><code>sts:AssumeRole</code> creates a role session. <strong><code>iam:PassRole</code> permits assigning an approved role to a service</strong>, such as configuring a Lambda to use its execution role; it does not give the caller a session as that role. Unrestricted role passing can let someone configure a powerful service even when their own direct permissions are limited. <a href="https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles_use_passrole.html" target="_blank" rel="noreferrer">AWS role-passing explanation</a>.</p><h2 id="how-a-denial-happens" tabindex="-1"><span class="hub-section-number">4 </span>How a denial happens <a class="header-anchor" href="#how-a-denial-happens" aria-label="Permalink to “4 How a denial happens”">​</a></h2><p>Access is denied unless an applicable permission allows it, and an applicable explicit deny overrides an allow. Organization controls, session policies, permissions boundaries and resource policies can further affect the result. A permissions boundary limits possible permissions; it does not grant permissions by itself.</p><p>For an unexpected denial, inspect the actual caller, action, resource and conditions. Then inspect the relevant identity policy and resource policy, including a KMS key policy when encryption is involved. Changing the application role to administrator may hide the cause and enlarge the damage possible from a bug.</p><h2 id="security-beyond-iam" tabindex="-1"><span class="hub-section-number">5 </span>Security beyond IAM <a class="header-anchor" href="#security-beyond-iam" aria-label="Permalink to “5 Security beyond IAM”">​</a></h2><p>TLS protects traffic; encryption at rest protects stored data. KMS controls encryption keys and their usage permissions. Secrets Manager stores sensitive configuration with access control and rotation features. Environment variables are configuration delivery, not a reason to commit a password.</p><p>CloudTrail supports investigation of AWS API activity. CloudWatch provides application and infrastructure telemetry. Neither should receive raw passwords or bearer tokens in log messages.</p><p>Prefer small permissions scoped to workload responsibilities, and review public and cross-account access with IAM Access Analyzer. <a href="https://docs.aws.amazon.com/IAM/latest/UserGuide/best-practices.html" target="_blank" rel="noreferrer">AWS security practices</a>.</p><p>Next: <a href="./storage-and-frontend.html">S3 and CloudFront</a>.</p>`,24)])])}const m=s(n,[["render",r]]);export{u as __pageData,m as default};
